credit_permutation_importance<-function(predictor,X,y,model_contract,feature_groups,permutations,design,loss_contract,row_metadata,weights=NULL,strata=NULL,custom_loss=NULL,support_evaluator=NULL,support_contract=NULL,context=NULL){
 checked<-.cr_ex_contract(model_contract,context);features<-checked$features;ctx<-checked$context;x<-.cr_pfs_matrix(X,'X');labels<-.cr_numeric(y,'y',vector_only=TRUE)
 if(!identical(dim(x),c(length(labels),length(features)))) .cr_error('PERMUTATION_SHAPE','Aligned held-out row matrix and labels required')
 n<-length(labels);w<-.cr_pf_weights(if(is.null(weights))rep(1,n)else weights,n);grouped<-.cr_ex_groups(feature_groups,features);groups<-grouped$ids;indices<-grouped$indices
 if(!.cr_object(design)) .cr_error('PERMUTATION_DESIGN','Explicit frozen evaluation design required');.cr_data_required(design,c('split','training_end','data_cutoff','train_row_ids','train_subject_ids','model_and_calibration_frozen','selection_use','permutation_design'))
 if(!design$split%in%c('OUT_OF_TIME','HOLDOUT')||!identical(design$model_and_calibration_frozen,TRUE)||design$selection_use!='FORBIDDEN'||!design$permutation_design%in%c('FIXED_PERMUTATIONS','IID_RANDOM_PERMUTATIONS')) .cr_error('PERMUTATION_DESIGN','Held-out frozen evaluation without feature selection and explicit permutation law required')
 train_end<-.cr_data_date(design$training_end,'training_end');cutoff<-.cr_data_date(design$data_cutoff,'data_cutoff');if(train_end>cutoff) .cr_error('PERMUTATION_DESIGN','Training cutoff cannot follow evaluation cutoff')
 for(k in c('train_row_ids','train_subject_ids')){v<-unlist(design[[k]],use.names=FALSE);if(length(v)&&(!is.character(v)||anyNA(v)||any(!nzchar(v))||anyDuplicated(v))) .cr_error('PERMUTATION_DESIGN','Explicit unique excluded training identities required')}
 rows<-.cr_data_rows(row_metadata,'row_metadata');if(length(rows)!=n) .cr_error('PERMUTATION_SHAPE','One evaluation metadata record per row required');ids<-character()
 for(row in rows){.cr_data_required(row,c('row_id','subject_id','observation_time','target_end','label_known_time'));ids<-c(ids,row$row_id);.cr_pfs_ids(list(row$subject_id),'subject_id');observed<-.cr_data_date(row$observation_time,'observation_time');end<-.cr_data_date(row$target_end,'target_end');known<-.cr_data_date(row$label_known_time,'label_known_time')
  if(row$row_id%in%unlist(design$train_row_ids)||row$subject_id%in%unlist(design$train_subject_ids)) .cr_error('PERMUTATION_LEAKAGE','Evaluation row or subject occurs in excluded fitting identities')
  if(!(observed<end&&end<=cutoff&&observed<=known&&known<=cutoff)||(design$split=='OUT_OF_TIME'&&observed<=train_end)) .cr_error('PERMUTATION_TIMING','Mature known outcomes and declared out-of-time observations required')
 };.cr_pfs_ids(ids,'row_ids');plan<-.cr_pfs_matrix(permutations,'permutations')
 if(ncol(plan)!=n||any(plan!=floor(plan))||any(plan<0)||any(plan>=n)) .cr_error('PERMUTATION_PLAN','Zero-based complete integer permutation rows required')
 if(any(vapply(seq_len(nrow(plan)),function(i)!all(sort(plan[i,])==seq_len(n)-1L),logical(1)))) .cr_error('PERMUTATION_PLAN','Each plan row must be a bijection')
 if(!is.null(strata)){strata<-unlist(strata);if(!is.character(strata)||length(strata)!=n||anyNA(strata)||any(!nzchar(strata))) .cr_error('PERMUTATION_STRATA','One explicit stratum label per row required');if(any(vapply(seq_len(nrow(plan)),function(i)any(strata!=strata[plan[i,]+1L]),logical(1)))) .cr_error('PERMUTATION_STRATA','Permutation must preserve every recipient stratum')}
 if(!.cr_object(loss_contract)) .cr_error('PERMUTATION_LOSS','Versioned loss contract required');.cr_data_required(loss_contract,c('loss_id','version','kind'));kind<-loss_contract$kind
 if(!kind%in%c('BRIER','LOG_LOSS','MSE','MAE','CUSTOM')||xor(kind=='CUSTOM',!is.null(custom_loss))) .cr_error('PERMUTATION_LOSS','Supported declared loss and matching custom callback required')
 if(kind%in%c('BRIER','LOG_LOSS')&&(model_contract$output_scale!='probability'||any(labels!=0&labels!=1))) .cr_error('PERMUTATION_LOSS','Binary probability loss requires binary mature outcomes')
 loss<-function(pred){
  if(kind%in%c('BRIER','MSE'))v<-(pred-labels)^2 else if(kind=='MAE')v<-abs(pred-labels)else if(kind=='LOG_LOSS'){v<-ifelse(labels==1,-log(pred),-log1p(-pred));if(any(!is.finite(v)&w>0)) .cr_error('PERMUTATION_INFINITE_LOSS','Positive-weight log loss is infinite; paired importance is not estimable without a separately declared model probability floor');v[w==0]<-0}else v<-tryCatch(custom_loss(labels,pred),error=function(e){if(inherits(e,'creditratingsystem_error'))stop(e);.cr_error('PERMUTATION_LOSS','Custom loss callback failed')})
  v<-.cr_numeric(v,'loss values',vector_only=TRUE);if(length(v)!=n) .cr_error('PERMUTATION_LOSS','One finite loss per evaluation row required');.cr_pfs_sum(w*v)
 }
 if(xor(is.null(support_evaluator),is.null(support_contract))||(!is.null(support_evaluator)&&!is.function(support_evaluator))) .cr_error('PERMUTATION_SUPPORT','Support evaluator and frozen support contract required together')
 if(!is.null(support_contract)){if(!.cr_object(support_contract)) .cr_error('PERMUTATION_SUPPORT','Versioned support contract required');.cr_data_required(support_contract,c('support_id','version'))}
 support<-function(z){if(is.null(support_evaluator))return(NULL);mask<-tryCatch(support_evaluator(z),error=function(e).cr_error('PERMUTATION_SUPPORT','Support callback failed'));if(!is.logical(mask)||!is.null(dim(mask))||length(mask)!=n||anyNA(mask)) .cr_error('PERMUTATION_SUPPORT','One boolean support flag per row required');list(unsupported_row_ids=as.list(ids[!mask]),unsupported_weight=sum(w*(!mask)))}
 base_pred<-.cr_ex_predict(predictor,x,model_contract);base_loss<-loss(base_pred);base_support<-support(x);reports<-list()
 for(j in seq_along(groups)){idx<-indices[[j]];losses<-numeric(nrow(plan));support_reports<-list()
  for(i in seq_len(nrow(plan))){z<-x;z[,idx]<-x[plan[i,]+1L,idx,drop=FALSE];losses[i]<-loss(.cr_ex_predict(predictor,z,model_contract));support_reports[i]<-list(support(z))}
  changes<-losses-base_loss;se<-if(design$permutation_design=='IID_RANDOM_PERMUTATIONS'&&nrow(plan)>1)stats::sd(changes)/sqrt(nrow(plan))else NULL
  reports[[j]]<-list(group_id=groups[j],feature_ids=as.list(features[idx]),permuted_losses=as.list(losses),loss_increases=as.list(changes),mean_loss_increase=mean(changes),permutation_standard_error=se,support_findings=support_reports)
 }
 means<-colSums(x*w);center<-sweep(x,2,means,'-');cov<-crossprod(center,center*w);sd<-sqrt(diag(cov));corr<-lapply(seq_along(features),function(i)lapply(seq_along(features),function(j)if(sd[i]==0||sd[j]==0)NULL else cov[i,j]/(sd[i]*sd[j])))
 .cr_result(list(baseline_loss=base_loss,baseline_predictions=as.list(base_pred),baseline_support=base_support,row_ids=as.list(ids),normalized_weights=as.list(w),groups=reports,feature_order=as.list(features),weighted_reference_correlation=corr,permutation_count=nrow(plan),design=design,loss_contract=loss_contract,support_status=if(is.null(support_evaluator))'NOT_ASSESSED'else'DECLARED_SUPPORT_CHECKED_WITHOUT_EXCLUDING_ROWS'),'explainability.credit_permutation_importance','loss_increase',ctx,diagnostics=list(model_contract_hash=.cr_hash(model_contract),data_hash=.cr_hash(list(X=.cr_pfs_rows(x),y=as.list(labels),row_metadata=rows)),permutation_hash=.cr_hash(.cr_pfs_rows(plan)),support_contract_hash=if(is.null(support_contract))NULL else .cr_hash(support_contract)),limitations='No fitting or feature selection is performed. Training exclusion and frozen status are declared provenance, not authenticated. Blocks are permuted jointly but dependence across blocks can be broken; correlation is descriptive. Unsupported rows remain in loss denominators. IID permutation standard errors concern permutation randomness only, not cohort, model or selection uncertainty. Fixed plans have no IID standard error.')
}
